Implementation:

```ts
function lcsLengths<T>(a, b, eq): number[] {
  // returns row of DP after processing all of a, columns indexed by b prefixes
  const prev = new Uint32Array(b.length + 1);
  const curr = new Uint32Array(b.length + 1);
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      curr[j] = eq(a[i-1], b[j-1]) ? prev[j-1] + 1 : Math.max(prev[j], curr[j-1]);
    }
    [prev, curr] swap — but swap with const arrays: use temp copy.
  }
}
```

Use let prev/curr and swap.

Hirschberg:

```ts
function hlcs(a, b, eq): T[] {
  const n = a.length, m = b.length;
  if (n === 0) return [];
  if (m === 0) return [];
  if (n === 1) {
    return b.some(y => eq(a[0], y)) ? [a[0]] : [];
  }
  const mid = n >> 1;
  const l1 = lcsLengths(a.slice(0, mid), b, eq); // length mid+1? lcsLengths returns array of size m+1 = score for prefix a[0..mid)
  const l2 = reverse lcsLengths of reversed a suffix vs reversed b.
  find j maximizing l1[j] + l2[m - j];
  return [...hlcs(a.slice(0,mid), b.slice(0,j)), ...hlcs(a.slice(mid), b.slice(j))];
}
```

lcsLengths returns Uint32Array of length m+1 where index j = LCS length of a-prefix vs b[0..j).

