result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/lcs.ts", "content": "/**
 * Longest common subsequence.
 *
 * Strategy: **Hirschberg's divide-and-conquer algorithm** (linear space).
 * The LCS *length* is computed with a rolling two-row DP over the shorter
 * dimension, i.e. O(min(|a|, |b|)) space. The full subsequence is then
 * recovered by recursively splitting `a` at its midpoint and finding the
 * optimal split point of `b` via one forward and one reverse length-row —
 * so traceback never materializes the full |a| x |b| table.
 */

/** One row of the DP length table: row[i][j] = LCS(x[0..i), y[0..j)) for all j,
 *  computed with only two rolling rows (O(|y|) space). */
function lengthRow<T>(x: readonly T[], y: readonly T[], eq: (u: T, v: T) => boolean): Uint32Array {
  const m = y.length;
  let prev = new Uint32Array(m + 1);
  let curr = new Uint32Array(m + 1);
  for (let i = 1; i <= x.length; i++) {
    const xi = x[i - 1]!;
    for (let j = 1; j <= m; j++) {
      curr[j] = eq(xi, y[j - 1]!) ? prev[j - 1]! + 1 : Math.max(prev[j]!, curr[j - 1]!);
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
    curr.fill(0);
  }
  return prev;
}

function hirschberg<T>(a: readonly T[], b: readonly T[], eq: (u: T, v: T) => boolean): T[] {
  const n = a.length;
  if (n === 0 || b.length === 0) return [];
  if (n === 1) {
    // Base case: a's single element is in the LCS iff it occurs somewhere in b.
    const [x] = a as readonly [T];
    return b.some((y) => eq(x!, y)) ? [x!] : [];
  }
  const mid = n >> 1;
  const prefix = a.slice(0, mid);
  const suffix = a.slice(mid);

  // Best split of b: maximize LCS(prefix, b[0..j)) + LCS(suffix, b[j..)).
  const leftRow = lengthRow(prefix, b, eq);
  const rightRow = lengthRow([...suffix].reverse(), [...b].reverse(), eq);

  let bestJ = 0;
  let bestScore = -1;
  for (let j = 0; j <= b.length; j++) {
    const score = leftRow[j]! + rightRow[b.length - j]!;
    if (score > bestScore) {
      bestScore = score;
      bestJ = j;
    }
  }
  return [
    ...hirschberg(prefix, b.slice(0, bestJ), eq),
    ...hirschberg(suffix, b.slice(bestJ), eq),
  ];
}

/**
 * Returns the longest common subsequence of `a` and `b`.
 * `eq` defaults to strict equality (`===`). Runs in O(n*m) time and
 * O(min(n, m)*something-small) extra space thanks to Hirschberg.
 */
export function lcs<T>(
  a: readonly T[],
  b: readonly T[],
  eq: (x: T, y: T) => boolean = (x, y) => x === y,
): T[] {
  return hirschberg(a, b, eq);
}
"})
