result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/diff.ts", "content": "import { lcs } from "./lcs";

export type DiffOp = "same" | "add" | "del";

export interface WordDiffEntry {
  op: DiffOp;
  word: string;
}

/**
 * Word-level diff: emits an ordered stream of operations that transforms
 * `oldWords` into `newWords` when replayed left to right.
 * The "same" runs follow an LCS of the two word arrays; everything between
 * matches is emitted as "del" (from old) and/or "add" (from new).
 */
export function diff(oldWords: string[], newWords: string[]): WordDiffEntry[] {
  const out: WordDiffEntry[] = [];
  let oi = 0;
  let ni = 0;

  for (const word of lcs(oldWords, newWords)) {
    while (oi < oldWords.length && oldWords[oi] !== word) {
      out.push({ op: "del", word: oldWords[oi++]! });
    }
    while (ni < newWords.length && newWords[ni] !== word) {
      out.push({ op: "add", word: newWords[ni++]! });
    }
    out.push({ op: "same", word });
    oi++;
    ni++;
  }

  while (oi < oldWords.length) out.push({ op: "del", word: oldWords[oi++]! });
  while (ni < newWords.length) out.push({ op: "add", word: newWords[ni++]! });

  return out;
}

/** Applies a diff produced by {@link diff} to `oldWords`, returning `newWords`. */
export function applyDiff(diffEntries: WordDiffEntry[]): string[] {
  const result: string[] = [];
  for (const { op, word } of diffEntries) {
    if (op === "add" || op === "same") result.push(word);
  }
  return result;
}
"})
