result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/lcs.test.ts", "content": "import { describe, expect, it } from "vitest";
import { lcs } from "../src/lcs";
import { applyDiff, diff } from "../src/diff";

/** Deterministic PRNG (mulberry32) so the property test is reproducible. */
function mulberry32(seed: number): () => number {
  let t = seed >>> 0;
  return () => {
    t = (t + 0x6d2b79f5) >>> 0;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r = (r + Math.imul(r ^ (r >>> 7), 61 | r)) ^ r;
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

const randInt = (rand: () => number, lo: number, hi: number) =>
  lo + Math.floor(rand() * (hi - lo + 1));

function pick<T>(rand: () => number, xs: readonly T[]): T {
  return xs[Math.floor(rand() * xs.length)]!;
}

describe("lcs", () => {
  it("returns empty for empty inputs", () => {
    expect(lcs([], [])).toEqual([]);
    expect(lcs(["a"], [])).toEqual([]);
    expect(lcs([], ["a", "b"])).toEqual([]);
  });

  it("handles classic cases", () => {
    expect(lcs([1, 3, 4, 1, 2, 3], [3, 4, 1, 2, 1, 3])).toEqual([3, 4, 1, 3]);
    expect(lcs("ABCBDAB".split(""), "BDCABA".split(""))).toEqual(
      // length must be 4; a valid LCS is B D A B
      expect.arrayContaining([]),
    );
    const got = lcs([..."ABCBDAB"], [..."BDCABA"]);
    expect(got).toHaveLength(4);
  });

  it("is symmetric in length on random inputs", () => {
    const rand = mulberry32(12345);
    const vocab = ["a", "b", "c", "d", "e"];
    for (let trial = 0; trial < 200; trial++) {
      const mk = () => Array.from({ length: randInt(rand, 0, 12) }, () => pick(rand, vocab));
      const a = mk();
      const b = mk();
      expect(lcs(a, b).length).toBe(lcs(b, a).length);
    }
  });
});

describe("diff", () => {
  it("reconstructs newWords from oldWords for 200 random pairs (property)", () => {
    const rand = mulberry32(0xc0ffee);
    const vocab = ["the", "quick", "brown", "fox", "jumps", "over", "lazy", "dog", "a", "b"];
    for (let trial = 0; trial < 200; trial++) {
      const oldWords = Array.from({ length: randInt(rand, 0, 25) }, () => pick(rand, vocab));
      const newWords = Array.from({ length: randInt(rand, 0, 25) }, () => pick(rand, vocab));
      const d = diff(oldWords, newWords);
      expect(applyDiff(d), `trial ${trial}: ${oldWords} -> ${newWords}`).toEqual(newWords);
    }
  });

  it("handles empty inputs", () => {
    expect(diff([], [])).toEqual([]);
    expect(diff(["x"], [])).toEqual([{ op: "del", word: "x" }]);
    expect(diff([], ["y"])).toEqual([{ op: "add", word: "y" }]);
  });

  it("emits only del+add for completely disjoint inputs", () => {
    const oldWords = ["cat", "sat", "mat"];
    const newWords = ["dog", "ran", "far"];
    const d = diff(oldWords, newWords);
    expect(d.every((e) => e.op === "del" || e.op === "add")).toBe(true);
    expect(d.filter((e) => e.op === "del").map((e) => e.word)).toEqual(oldWords);
    expect(d.filter((e) => e.op === "add").map((e) => e.word)).toEqual(newWords);
  });
});
"})
